    warn: 'Флаги блока game { ... } пишутся в самом верху файла внутри game "Название" { ... }, а не внутри on start!',
    code: '// 1) Флаги в шапке game (достаточно просто написать имя флага):\ngame "MyGame" {\n  size: 800x500\n  NoLocalStorage     // то же самое, что noLocalStorage: true\n  ySort              // то же самое, что ySort: true\n  pixelated          // то же самое, что pixelated: true\n}\n\n// 2) Флаги внутри сущности:\nentity Hero {\n  x: 100, y: 200, z: 5\n  ySort: false\n  alive: true\n}\n\n// 3) Флаги-переключатели во время игры (вызов как функции):\non start {\n  debug(true)        // или клавиша F3\n  setMuted(false)\n}'
