function resolveRoySignatureHint(textBeforeCursor) {
  const s = String(textBeforeCursor || "");
  if (!s) return null;
  let inStr = null;
  const openStack = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inStr) {
      if (ch === "\\") {
        i++;
        continue;
      }
      if (ch === inStr) inStr = null;
      continue;
    }
    if (ch === '"' || ch === "'") {
      inStr = ch;
      continue;
    }
    if (ch === "/" && s[i + 1] === "/") {
      const nl = s.indexOf("\n", i);
      if (nl < 0) break;
      i = nl;
      continue;
    }
    if (ch === "(") {
      openStack.push({ pos: i, commas: 0 });
    } else if (ch === ")" && openStack.length > 0) {
      openStack.pop();
    } else if (ch === "," && openStack.length > 0) {
      openStack[openStack.length - 1].commas += 1;
    }
  }
  if (openStack.length === 0) return null;
  const activeCall = openStack[openStack.length - 1];
  const beforeParen = s.slice(0, activeCall.pos).trimEnd();
  const m = /([a-zA-Z_][a-zA-Z0-9_]*)$/.exec(beforeParen);
  if (!m) return null;
  const fnName = m[1];
  const entry = ROY_SIGNATURE_HINTS[fnName];
  if (!entry) return null;
  return {
    fnName,
    params: entry.params,
    activeIdx: Math.min(activeCall.commas, Math.max(0, entry.params.length - 1)),
    tip: entry.tip
  };
}
